usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Certificates.List(
		context.TODO(),
		openai.AdminOrganizationCertificateListParams{
			Limit: param.NewOpt[int64](20),
			After: param.NewOpt[string]("after"),
			Order: param.NewOpt[openai.AdminOrganizationCertificatesListOrder](openai.AdminOrganizationCertificatesListOrderAsc),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
